mapper.select:
SELECT A.* FROM ( SELECT ROWNUM AS rnum, B.* FROM ( SELECT q.QNA_NO AS qnaNo, q.USER_ID AS userId, q.QNA_TITLE AS qnaTitle,
u.USER_NAME AS writerName, u.ROLE AS writerRole,
TO_CHAR(q.QNA_CREATED, 'YYYY-MM-DD') AS createdAt, q.QNA_STATUS AS qnaStatus, q.IS_NOTICE AS isNotice, NVL(q.QNA_HIT, 0) AS hit FROM QNA_BOARD q JOIN USERS u ON u.USER_ID = q.USER_ID WHERE 1=1 AND q.IS_NOTICE = 'N' AND NVL(q.DEL_YN,'N') = 'N'
AND q.QNA_TITLE LIKE '%' || #{svo.sword} || '%'
AND q.USER_ID LIKE '%' || #{svo.sword} || '%'
AND q.QNA_CTT LIKE '%' || #{svo.sword} || '%'
ORDER BY q.QNA_CREATED DESC ) B
WHERE ROWNUM <= #{end}
) A
WHERE A.rnum >= #{start}

mapper.update:
UPDATE QNA_BOARD
SET QNA_HIT = QNA_HIT + 1
WHERE QNA_NO = #{value}

mapper.delete:
DELETE FROM QNA_BOARD
WHERE QNA_NO = #{qnaNo}    
  AND USER_ID = #{userId}

mapper.select:
SELECT x.qnaNo, x.qnaTitle, x.qnaCtt, x.userId, x.createdAt, x.qnaStatus, x.ansCtt, x.ansAt, x.displayNo FROM ( SELECT q.QNA_NO AS qnaNo, q.QNA_TITLE AS qnaTitle, q.QNA_CTT AS qnaCtt, q.USER_ID AS userId, TO_CHAR(q.QNA_CREATED, 'YYYY-MM-DD') AS createdAt,
/* 의미: 답변이 있으면 DONE, 없으면 WAIT */ CASE WHEN q.ANS_CTT IS NULL OR TRIM(q.ANS_CTT) = '' THEN 'WAIT' ELSE 'DONE' END AS qnaStatus,
q.ANS_CTT AS ansCtt, TO_CHAR(q.ANS_AT, 'YYYY-MM-DD') AS ansAt,
/* ✅ 의미: 게시판 문의목록과 동일한 "화면용 번호(공백 없는 순번)" */ /* ✅ 존재이유: DB qnaNo(식별자)는 공백이 생길 수 있으니, 목록 표시번호는 삭제 여부에 따라 자동으로 당겨지게 맞추기 위함 */ (COUNT(*) OVER() - ROW_NUMBER() OVER(ORDER BY q.QNA_CREATED DESC, q.QNA_NO DESC) + 1 ) AS displayNo
FROM QNA_BOARD q WHERE q.IS_NOTICE = 'N' AND NVL(q.DEL_YN,'N') = 'N' ) x WHERE x.userId = #{value} ORDER BY x.qnaNo DESC
